Properties props = new Properties();
props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, JsonSerializer.class.getName());

// Creating a KafkaProducer sending state updates for compacted logs
KafkaProducer<String, UserState> producer = new KafkaProducer<>(props);

// Sending a valid state update
producer.send(new ProducerRecord<>("user-state-topic", "user_123", new UserState("Active", 30)));

// Sending a tombstone marker to delete the key's state during log compaction
producer.send(new ProducerRecord<>("user-state-topic", "user_123", null));
producer.close();
